function cell(r,label,index){
 if(label.includes('编号'))return r.id;
 if(label.includes('名称')||label==='标题'||label==='作品'||label==='问题'||label==='资源'||label==='数据对象'||label==='关联对象')return r.title||r.name||r.question;
 if(label.includes('姓名')||label.includes('申请人')||label.includes('操作人')||label.includes('负责人')||label.includes('审核人'))return r.owner||r.name||r.role||'管理员A';
 if(label.includes('单位')||label.includes('租户'))return r.tenant;
 if(label==='角色')return r.role||'内容编辑';
 if(label.includes('手机号'))return r.phone||'138****0000';
 if(label.includes('时间')||label.includes('日期'))return new Date(r.updatedAt||r.time||r.createdAt||Date.now()).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
 if(label.includes('期限'))return r.rightsUntil||'未授权';
 if(label.includes('状态')||label.includes('结论'))return r.status||'已配置';
 if(label.includes('AI预审'))return r.aiReviewed?'已通过':'待预审';
 if(label.includes('人工终审'))return r.approved?'已通过':r.status==='已驳回'?'已驳回':'待终审';
 if(label.includes('版本')||label==='固件')return r.version||r.firmware||r.knowledgeVersion||'v1.0.0';
 if(label.includes('电量'))return (r.battery??86)+'%';
 if(label.includes('在线'))return r.online?'在线':'离线';
 if(label.includes('权限')||label.includes('范围')||label.includes('用途'))return r.scope||'本单位数据';
 if(label.includes('权利人'))return r.rightsHolder||'未登记';
 if(label.includes('指纹'))return r.fingerprint?.slice(0,20)||'未生成';
 if(label.includes('来源'))return r.source||'县方演示资料';
 if(label.includes('类型')||label.includes('分类')||label.includes('类别'))return r.type||r.category||'非遗文化';
 if(label.includes('操作'))return r.action||'配置保存';
 if(label.includes('路径'))return '/api/demo/'+P.mod;
 if(label.includes('调用方')||label.includes('应用'))return '线上非遗馆';
 if(label.includes('数量')||label.includes('条目')||label.includes('量')||label.includes('资源数'))return r.resources?.length||r.knowledge?.length||128+index*36;
 if(label.includes('语种'))return '中文';
 if(label.includes('进度'))return r.progress!==undefined?r.progress+'%':'已完成';
 return r.fields?.[label]||r.category||'已配置';
}
