 const headers=[...table.querySelectorAll('thead th')].map(el=>el.textContent.trim());const readonly=['007','017','054','092','122'].includes(P.id);table.querySelector('tbody').innerHTML=list.length?list.slice(0,10).map((r,i)=>`<tr data-record="${escape(r.id)}">${headers.map((label,j)=>label==='操作'?`<td><button class="btn" data-detail="${escape(r.id)}" style="padding:5px 9px;min-height:29px;font-size:11px">详情</button>${!readonly?` <span class="link" data-edit="${escape(r.id)}">编辑</span>`:''}</td>`:`<td>${/状态|结论|AI预审|人工终审/.test(label)?'<span class="pill '+(/待|驳回|过期|异常/.test(String(cell(r,label,i)))?'amber':'')+'">'+escape(cell(r,label,i))+'</span>':escape(cell(r,label,i))}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="rt-table-empty">暂无匹配记录。可以新建、导入或调整筛选条件。</td></tr>`;
