function business(){
 if(['4.1','4.2'].includes(P.mod))return contentFlow();
 if(P.mod==='4.4')return reviewFlow();if(P.mod==='4.5')return publishFlow();
 if(['2.3','2.4'].includes(P.mod))return knowledgeFlow();
 if(['6.1','6.2','6.3'].includes(P.mod))return resourceFlow();
 if(P.mod==='6.5')return hallFlow();
 if(P.mod==='5.3')return P.id==='103'?rentalFlow():P.id==='104'?rentalFlow(true):deviceFlow();
 if(P.mod==='5.2')return P.id==='099'?packageFlow():configFlow();
 if(P.mod==='2.2')return importer();if(['3.2','3.3'].includes(P.mod))return askDialog();
 if(P.mod==='3.4')return evaluate();return configFlow();
}
