async function souvenir(title,photo='',style='山水青绿'){
 const canvas=document.createElement('canvas');canvas.width=1179;canvas.height=1770;const ctx=canvas.getContext('2d');ctx.fillStyle=style==='龙灯朱红'?'#a44836':style==='非遗金色'?'#92713e':'#143f35';ctx.fillRect(0,0,canvas.width,canvas.height);const art=new Image();art.src='/culture.svg';await art.decode();ctx.drawImage(art,0,390,1179,800);ctx.fillStyle='#eee0ba';ctx.textAlign='center';ctx.font='52px Microsoft YaHei';ctx.fillText('慈利 · 非遗有声',589,140);ctx.font='74px Microsoft YaHei';ctx.fillText(title.slice(0,14),589,300);if(photo){const image=new Image();image.src=photo;await image.decode();ctx.save();ctx.beginPath();ctx.roundRect(370,610,440,550,40);ctx.clip();ctx.drawImage(image,370,610,440,550);ctx.restore()}ctx.font='38px Microsoft YaHei';ctx.fillText('一灯一故事，一城一传承',589,1370);ctx.font='24px Microsoft YaHei';ctx.fillText('AI模拟生成 · 仅为产品演示',589,1630);return canvas.toDataURL('image/png');
}
